require'json';require'fileutils';root=File.expand_path('..',__dir__);source=JSON.parse(File.read(File.join(root,'protocol/aoo-protocol-v2.json')));doc=File.read(File.join(root,'docs/generated/protocol-reference.md'));ids=source.fetch('messages').map{|m|m.fetch('msgId')};checks={all_messages_documented:ids.all?{|id|doc.include?("## `#{id}`")},field_tables:doc.scan('### 请求字段').length==ids.length&&doc.scan('### 响应字段').length==ids.length,metadata: %w[版本 方向 传输 鉴权 幂等 错误码].all?{|x|doc.include?(x)},examples:doc.scan('```json').length==ids.length,generated_warning:doc.include?('自动生成')&&doc.include?('禁止手工编辑')};checks[:passed]=checks.values.all?;out=File.join(root,'docs/generated/proto09-protocol-docs.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(checks.merge(messageCount:ids.length,reference:'docs/generated/protocol-reference.md'))+"\n");abort('PROTO09 docs audit failed')unless checks[:passed]
